    let mean = mean_residual.max(0.0);
    let next = next_item_size as f64;

    let fill = 1.0 - (residual / capacity);
    let post_fill = 1.0 - (post / capacity);
    let progress_term = progress * progress;
    let curved_progress = progress_term * (1.0 + 0.35 * (1.0 - progress));

    let mut score = post;
    score += 45.0 * (post / capacity).powi(2) * (1.0 + curved_progress);
    score -= 12.0 * (post_fill.powi(2)) * progress_term;
