    score += 18.0 * (1.0 - fill) * progress * (1.0 - progress);
    score -= 20.0 * (post_fill * progress_term);

    if next > 0.0 {
        let lookahead_need = next / capacity;
        let future_gap = (post / capacity - lookahead_need).max(0.0);
        score += 30.0 * future_gap * (1.0 - progress_term);
        score -= 10.0 * (post_fill * lookahead_need);
