pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).min(1.0)
    };

    let is_new_bin = bin_residual >= bin_capacity;
    let post_fraction = post / capacity;
    let item_fraction = item / capacity;
    let mean_fraction = (mean / capacity).min(1.0);

    score += post * post / capacity;
    score += (capacity - post) * (capacity - post) / capacity;

    if next > 0.0 {
        let modular_fit = (post as u32) % next as u32;
        let modular_penalty = (modular_fit as f64) / next;
        let class_penalty = if post < next {
            24.0 * (next - post) / next
        } else {
            6.0 * modular_penalty
        };
        score += class_penalty;

        let next_fraction = (next / capacity).min(1.0);
        let threshold = (capacity * next_fraction).floor();
        let quantized = (post / threshold.max(1.0)).floor();
        score += quantized * 2.0;
    } else {
        score += post * 0.65;
    }

    let scarcity = if fitting_bins_count == 0 {
        120.0
    } else if fitting_bins_count == 1 {
        30.0
    } else {
        (10.0 / fitting_bins_count as f64).min(10.0)
    };
    score += scarcity;

    if is_new_bin {
        score -= 18.0 * (1.0 - progress);
        score -= 8.0 * mean_fraction;
        score += item_fraction * 12.0;
    } else {
        score -= (residual / capacity) * 14.0;
        score -= (1.0 - post_fraction) * 10.0;

        if post < next && next > 0.0 {
            score += 20.0;
        }

        if post <= 5 {
            score += 28.0;
        } else if post <= 10 {
            score += 16.0;
        } else if post <= 20 {
            score += 7.0;
        }

        if mean > 0.0 {
            let balance = (post - mean).abs() / capacity;
            score += balance * 8.0;
        }

        if open_bins_count > 1 && fitting_bins_count > 1 {
            score += 3.0;
        }
    }

    if progress > 0.75 {
        score -= (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let item = item_size as f64;
    let capacity = bin_capacity as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual as f64;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Dead space that cannot plausibly be used by the observed item stream.
    let dead_threshold = (item / 2.0).min(15.0);
    if (post_residual as f64) < dead_threshold {
        let excess = dead_threshold - post_residual as f64;
        score += 2.5 * excess;
    }

    // Strongly prefer exact or near-exact closure of a bin.
    score -= (1.0 - residual / capacity.max(1.0)) * 8.0;

    // Avoid leaving a large remainder unless it is especially useful for lookahead.
    if post_residual > 0 {
        score += (post_residual as f64).sqrt() * 0.35;
    }

    // Reward a tight fit, especially when this is the only remaining fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + (residual - item).min(20.0) as f64 * 0.20;
    }

    // Prefer bins whose remaining capacity is close to the current/lookahead item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let next_gap = (post_residual as f64 - next).abs();
        score += next_gap * 0.20;
        if post_residual as f64 >= next {
            score -= 2.0;
        }
    } else {
        score -= progress * (post_residual as f64) * 0.015;
    }

    // With many open bins, pressure residuals toward useful, non-wasteful space.
    let pressure = (open_bins_count as f64).sqrt();
    score += pressure * 0.20;
    if mean > 0.0 {
        score += ((residual - mean) * 0.10).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        score -= 24.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual + next_item_size > bin_capacity {
            score -= 8.0;
        } else {
            score += 14.0;
        }
    }

    let relative_residual = post_residual as f64 - mean_residual;
    score -= 0.35 * relative_residual;

    if post_residual < item_size.min(next_item_size.max(1)) {
        score += 18.0;
    }

    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    score += 5.0 * progress;

    if open_bins_count == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / (total_items as f64).max(1.0)
    };

    let fill_before = 1.0 - residual / capacity;
    let fill_after = 1.0 - post / capacity;
    let dead_space_penalty = if post < item {
        (item - post) * (1.0 + 2.5 * progress)
    } else {
        0.0
    };
    let tight_fit_bonus = (residual - item).abs() * 0.35;
    let fragmentation_penalty = post * (0.25 + 0.75 * progress);
    let global_alignment = (post - mean) * 0.08;
    let pressure = if open_bins_count == 0 {
        0.0
    } else {
        item / (mean + item + 1.0)
    };
    let opportunity_cost = if fitting_bins_count <= 1 {
        18.0 + 22.0 * progress
    } else {
        0.0
    };
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * (0.30 + 0.90 * (1.0 - progress))
    } else if next_item_size > 0 && post >= next_item_size as f64 {
        -(2.0 + 4.0 * progress)
    } else {
        0.0
    };
    let new_bin_bonus = if bin_residual == bin_capacity {
        -(8.0 + 10.0 * (1.0 - progress))
    } else {
        0.0
    };

    score += dead_space_penalty
        + fragmentation_penalty
        + global_alignment
        + opportunity_cost
        + lookahead_penalty
        + new_bin_bonus
        - tight_fit_bonus
        - 6.0 * fill_after
        - 3.0 * pressure
        + 4.0 * fill_before;

    score
}
